const fs=require('node:fs'),crypto=require('node:crypto');
const R='/root/autodl-tmp/symbolic_dynamics/docs/papers211_215_sequence/reviews/p212_b/build01';
const D='docs/papers211_215_sequence/qa/p212_b_build_artifact_independent01/DATA.stdout.raw';
const raw=fs.readFileSync(D), d=JSON.parse(raw);const sha=b=>crypto.createHash('sha256').update(b).digest('hex');
function ok(v,m){if(!v)throw Error(m);}
ok(Buffer.from(JSON.stringify(d,null,2)+'\n').equals(raw),'complete JSON wire');
for(const x of d.inventory){const b=fs.readFileSync(R+'/'+x.path);ok(b.length===x.bytes&&sha(b)===x.sha256,'artifact '+x.path);}
for(const x of d.complete_text_captures){const b=fs.readFileSync(R+'/'+x.path);ok(Buffer.from(x.raw_utf8).equals(b)&&sha(b)===x.sha256,'whole text '+x.path);}
for(const x of d.external_pins){ok(x.path.startsWith('/root/autodl-tmp/symbolic_dynamics/'),'workspace');const b=fs.readFileSync(x.path);ok(b.length===x.bytes&&sha(b)===x.sha256,'external '+x.path);}
for(const x of d.ordered_fls){const lines=fs.readFileSync(R+'/pass_artifacts/'+x.pass+'.after/main.fls','utf8').trimEnd().split('\n');ok(JSON.stringify(lines)===JSON.stringify(x.events.map(e=>e.raw)),'every ordered FLS '+x.pass);ok(x.events.every((e,i)=>e.line===i+1&&!e.role.startsWith('UNKNOWN')),'FLS roles');}
const names=[];function walk(p,r=''){for(const x of fs.readdirSync(p,{withFileTypes:true})){ok(!x.isSymbolicLink(),'nonlink');if(x.isDirectory())walk(p+'/'+x.name,r+x.name+'/');else names.push(r+x.name);}}walk(R);ok(JSON.stringify(names.sort())===JSON.stringify(d.inventory.map(x=>x.path).sort()),'whole membership');
ok(d.findings.length===0&&d.summary.findings===0,'no findings');ok(fs.readFileSync(D).equals(raw),'DATA stable');
console.log(JSON.stringify({complete_data_bytes:raw.length,sha256:sha(raw),inventory:d.inventory.length,text_captures:d.complete_text_captures.length,external:d.external_pins.length,ordered_events:d.ordered_fls.reduce((n,x)=>n+x.events.length,0),raw_wire_and_all_whole_payloads:true,stderr_bytes:fs.readFileSync('docs/papers211_215_sequence/qa/p212_b_build_artifact_independent01/DATA.stderr.raw').length,commands:d.commands.map(x=>({label:x.label,cwd:x.cwd,argv:x.supervisor_argv,exit:x.supervisor_exit})),snapshots:d.snapshots,raw_pairs:d.raw_pairs,diagnostics:d.diagnostics,locator:d.adaptation.citation_locator},null,2));
NODE

